<?php declare(strict_types=1);require dirname(__DIR__).'/_bootstrap.php';$user=api_user();if(($_SERVER['REQUEST_METHOD']??'GET')==='GET'){require_get();$s=db()->prepare('SELECT id,method_type,account_holder,account_masked,ifsc,status,created_at FROM user_payment_methods WHERE user_id=? ORDER BY id DESC');$s->execute([$user['id']]);json_response(true,'Saved payout methods',['items'=>$s->fetchAll()]);}require_post();$d=json_input();$type=strtoupper((string)($d['method_type']??''));$holder=trim((string)($d['account_holder']??''));$account=trim((string)($d['account_reference']??''));$ifsc=strtoupper(trim((string)($d['ifsc']??'')));if(!in_array($type,['BANK','UPI'],true)||$holder===''||$account===''||($type==='BANK'&&!preg_match('/^[A-Z]{4}0[A-Z0-9]{6}$/',$ifsc))||($type==='UPI'&&!preg_match('/^[A-Za-z0-9._-]{2,64}@[A-Za-z]{2,32}$/',$account)))json_response(false,'Valid bank/UPI payout details are required.',null,422);if($type==='BANK'&&!preg_match('/^[0-9]{6,24}$/',preg_replace('/\s+/','',$account)??''))json_response(false,'Bank account number is invalid.',null,422);$masked=$type==='UPI'?substr($account,0,2).'***'.strrchr($account,'@'):'XXXX XXXX '.substr(preg_replace('/\s+/','',$account)??'',-4);db()->prepare('INSERT INTO user_payment_methods(user_id,method_type,account_holder,account_reference_encrypted,account_masked,ifsc,status) VALUES(?,?,?,?,?, ?,"ACTIVE")')->execute([$user['id'],$type,$holder,encrypt_secret($account),$masked,$type==='BANK'?$ifsc:null]);log_security((int)$user['id'],'PAYOUT_METHOD_ADDED','LOW','A payout method was added',['method_type'=>$type]);json_response(true,'Payout method saved',['account_masked'=>$masked],201);
